// VirtualKeyboard.cpp -- hand-owned since the constructor was added.
//
// The accessor part (Startup) was generated by tools/gen_accessors.py
// and is kept as it was written; gen_units.py now HOLDS this file
// rather than regenerating it. The constructor was read from the image
// with tools/disasm.py, and the layout from the DWARF: System::Module
// is a name, an EventSet of four ints, and then its virtuals, so the
// vptr lands at 0x14 -- the same base GameWindow.cpp already matches
// with -- and the constructor stores 67 into the first event stage.

namespace System {

class Module {
public:
    Module();

    char* name;
    int stage[4];
};

}  // namespace System

namespace IO {

class VirtualKeyboardModule : public System::Module {
public:
    virtual void __vtable_anchor();
    VirtualKeyboardModule();
    void Startup(int a0);

    unsigned char _pad0[0x80];
    int curState;
    int currentContext;
};

}  // namespace IO

#pragma dont_inline on
IO::VirtualKeyboardModule::VirtualKeyboardModule() : System::Module() {
    stage[0] = 67;
}
#pragma dont_inline off

void IO::VirtualKeyboardModule::Startup(int a0) {
    curState = 0;
    currentContext = 0;
}
